// Scoring for the web version. A line-for-line port of Sources/TalentFinderCore/Scoring.swift:
// same loop order, same arithmetic, same tie-breaks, so results match the Mac app exactly.
// tests/scoring.test.mjs checks this against fixtures generated by the Swift code.

/** Whether `value` is a valid answer to question `q`. */
export function accepts(q, value) {
  if (!Number.isInteger(value)) return false;
  return q.kind === "choice" ? value >= 0 && value < q.options.length : value >= 1 && value <= 5;
}

/** Wraps text in curly quotes unless it already starts with one. */
export function quoted(text) {
  return text.startsWith("“") ? text : `“${text}”`;
}

function evidenceText(q, value) {
  const label = q.scaleLabels[value - 1].toLowerCase();
  if (q.kind === "ability") return `${q.prompt} — ${label}`;
  if (q.reversed) return `You disagreed: ${quoted(q.prompt)}`;
  return `You ${label === "strongly agree" ? "strongly agreed" : "agreed"}: ${quoted(q.prompt)}`;
}

/** Strongest first; ties keep their original order. Returns the first `n` items' values. */
function topByWeight(pairs, n) {
  return pairs
    .map((p, i) => [p, i])
    .sort((a, b) => (a[0][1] !== b[0][1] ? b[0][1] - a[0][1] : a[1] - b[1]))
    .slice(0, n)
    .map(([p]) => p[0]);
}

const byName = (a, b) => (a < b ? -1 : a > b ? 1 : 0);

/**
 * Turns answers into aptitude scores and activity matches.
 * @param {Record<string, number>} answers question id → 1–5 for scale items, option index for choice items
 * @param {object} survey the contents of data/survey.json
 */
export function score(answers, survey) {
  const order = survey.aptitudes.map((a) => a.id);
  const names = Object.fromEntries(survey.aptitudes.map((a) => [a.id, a.name]));
  const earned = {}, possible = {}, evidence = {};
  let answered = 0;

  for (const q of survey.questions) {
    const value = answers[q.id];
    if (value === undefined || !accepts(q, value)) continue;
    answered += 1;
    if (q.kind === "choice") {
      const chosen = q.options[value];
      for (const d of order) {
        if (!q.options.some((o) => d in o.weights)) continue;
        possible[d] = (possible[d] ?? 0) + Math.max(...q.options.map((o) => o.weights[d] ?? 0));
        const w = chosen.weights[d];
        if (w !== undefined) {
          earned[d] = (earned[d] ?? 0) + w;
          (evidence[d] ??= []).push([`You picked ${quoted(chosen.text)}`, w]);
        }
      }
    } else {
      let level = (value - 1) / 4;
      if (q.reversed) level = 1 - level;
      for (const d of order) {
        const w = q.weights[d];
        if (w === undefined) continue;
        earned[d] = (earned[d] ?? 0) + w * level;
        possible[d] = (possible[d] ?? 0) + w;
        if (level > 0.5) (evidence[d] ??= []).push([evidenceText(q, value), w * level]);
      }
    }
  }

  const scores = order
    .map((d) => {
      const p = possible[d] ?? 0;
      return { aptitude: d, score: p > 0 ? ((earned[d] ?? 0) / p) * 100 : 0, evidence: topByWeight(evidence[d] ?? [], 3) };
    })
    .sort((a, b) => (a.score !== b.score ? b.score - a.score : byName(names[a.aptitude], names[b.aptitude])));

  return { answeredCount: answered, scores, matches: match(scores, survey.activities, order) };
}

function match(scores, activities, order) {
  const byDim = Object.fromEntries(scores.map((s) => [s.aptitude, s.score]));
  return activities
    .map((a) => {
      const weighted = order.filter((d) => d in a.weights).map((d) => [d, a.weights[d]]);
      const total = weighted.reduce((s, [, w]) => s + w, 0);
      const parts = weighted.map(([d, w]) => [d, w * (byDim[d] ?? 0)]);
      const fit = total > 0 ? parts.reduce((s, [, x]) => s + x, 0) / total : 0;
      return { activity: a.name, category: a.category, fit, reasons: topByWeight(parts, 2) };
    })
    .sort((a, b) => (a.fit !== b.fit ? b.fit - a.fit : byName(a.activity, b.activity)));
}

/** A fresh survey over every question, optionally shuffled. */
export function newProgress(survey, shuffled, random = Math.random) {
  const order = survey.questions.map((q) => q.id);
  if (shuffled) {
    for (let i = order.length - 1; i > 0; i--) {
      const j = Math.floor(random() * (i + 1));
      [order[i], order[j]] = [order[j], order[i]];
    }
  }
  return { order, answers: {}, currentIndex: 0, startedAt: new Date().toISOString() };
}

export const isComplete = (p) => p.order.every((id) => p.answers[id] !== undefined);
